// ROOM gallery (interior designer): the entrance hall behind the orange door. Inner air is the box [16,2,10,22,4,10]:
// one cell deep (z=10), seven long (x=16..22). The 2-high lane along z=10 is the only walkable row, so nothing solid
// stands in it. The design is what fits beside it: orange carpet runner on the floor (walkable), two hung lanterns
// over the lane (y=4, clear of the 2-high walk) that light the hall, and nothing on the thresholds at x=16 and x=22
// (kitchen and corridor openings) or under the atrium doors at x=19..20.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // origin [16,2,10]: rows run along +x (x=16..22); one row (z=10). Layer 0 = y=2 (floor level), layer 1 = y=3, layer 2 = y=4.
  layers(g, [16, 2, 10], {
    c: "orange_carpet",
    L: ["lantern", { hanging: "true", waterlogged: "false" }],
  }, [
    [[" ccccc "], [" ccccc "], []],
  ]);
}

